import { randomBytes } from "node:crypto"
import { existsSync, writeFileSync } from "node:fs"
import { resolve } from "node:path"

const root = resolve(import.meta.dirname, "..")
const envFile = resolve(root, process.env.GEI_ENV_FILE || ".env")

if (existsSync(envFile)) {
  console.log(`Local configuration already exists and was preserved: ${envFile}`)
  process.exit(0)
}

const secret = () => randomBytes(32).toString("base64")
const body = [
  "# Local development configuration. Generated by pnpm setup:dev; never commit this file.",
  "NODE_ENV=development",
  "BACKEND_HOST=127.0.0.1",
  "BACKEND_PORT=3001",
  "PUBLIC_ORIGIN=http://localhost:8443",
  "DATABASE_URL=postgresql://postgres:postgres@127.0.0.1:56322/postgres",
  "DATABASE_ROLE=gei_backend",
  `AUTH_CODE_PEPPER=${secret()}`,
  `EMAIL_CHANGE_CODE_PEPPER=${secret()}`,
  `CSRF_HMAC_SECRET=${secret()}`,
  `RATE_LIMIT_KEY_PEPPER=${secret()}`,
  "METRICS_ENABLED=true",
  "REALTIME_ENABLED=true",
  "",
].join("\n")

try {
  writeFileSync(envFile, body, { encoding: "utf8", flag: "wx", mode: 0o600 })
  console.log(`Created local development configuration: ${envFile}`)
} catch (error) {
  if ((error).code === "EEXIST") {
    console.log(`Local configuration already exists and was preserved: ${envFile}`)
  } else {
    throw error
  }
}
